/** Fixture supplies raw sources and stations; all mining, extraction, heat and containers use real input packets. */
public final class AcquisitionFlowTest implements FabricClientGameTest {
    private static final BlockPos MILL=new BlockPos(0,100,0),PRESS=new BlockPos(2,100,0),FAT=new BlockPos(4,100,0),SALT=new BlockPos(6,100,0),MIX=new BlockPos(4,100,2),RICE=new BlockPos(2,100,2);
    private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
    private static KitchenBlockEntity pot(MinecraftServer g,BlockPos p){return (KitchenBlockEntity)g.overworld().getBlockEntity(p);}
    private static int count(MinecraftServer g,String id){return g.getPlayerList().getPlayers().getFirst().getInventory().countItem(KitchenContent.item(id));}
    private static void equip(ClientGameTestContext c,TestServerContext s,String id){
        c.runOnClient(client->{client.player.getInventory().setSelectedSlot(8);if(!client.player.getMainHandItem().isEmpty())client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,44,0,net.minecraft.world.inventory.ContainerInput.QUICK_MOVE,client.player);});c.waitTicks(3);s.runCommand("item replace entity @a hotbar.8 with "+id);c.waitTicks(5);
    }
    private static void select(ClientGameTestContext c,String id){c.runOnClient(client->{for(int i=0;i<36;i++)if(!client.player.getInventory().getItem(i).isEmpty()&&ResourceStates.baseId(client.player.getInventory().getItem(i)).equals(id)){if(i>8){client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,i,7,net.minecraft.world.inventory.ContainerInput.SWAP,client.player);client.player.getInventory().setSelectedSlot(7);}else client.player.getInventory().setSelectedSlot(i);return;}throw new AssertionError("Actual output missing: "+id);});c.waitTicks(5);}
    private static void tp(ClientGameTestContext c,TestServerContext s,String coords){s.runCommand(coords);c.waitTicks(8);}
    private static void click(ClientGameTestContext c,BlockPos p,Direction face){c.runOnClient(client->client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(p),face,p,false)));c.waitTicks(6);}
    private static void take(ClientGameTestContext c,TestServerContext s,BlockPos p,int times){equip(c,s,"minecraft:air");c.getInput().holdKey(o->o.keyShift);c.waitTicks(3);for(int i=0;i<times;i++){if(i>0)equip(c,s,"minecraft:air");click(c,p,Direction.UP);}c.getInput().releaseKey(o->o.keyShift);c.waitTicks(3);}
    private static boolean observe(TestServerContext s,Predicate<MinecraftServer> condition){boolean[] result={false};s.runOnServer(g->result[0]=condition.test(g));return result[0];}
    private static void until(ClientGameTestContext c,TestServerContext s,Predicate<MinecraftServer> condition,int ticks,String message){for(int n=0;n<ticks;n+=20){if(observe(s,condition))return;c.waitTicks(20);}check(observe(s,condition),message);}
    private static void lookAt(ClientGameTestContext c,Vec3 p){c.runOnClient(client->{var d=p.subtract(client.player.getEyePosition());client.player.setYRot((float)(Math.toDegrees(Math.atan2(d.z,d.x))-90));client.player.setXRot((float)-Math.toDegrees(Math.atan2(d.y,Math.sqrt(d.x*d.x+d.z*d.z))));});c.waitTicks(8);}
    private static void useWater(ClientGameTestContext c){lookAt(c,new Vec3(2.5,99.8,5.5));c.runOnClient(client->client.gameMode.useItem(client.player,InteractionHand.MAIN_HAND));c.waitTicks(8);}
    @Override public void runTest(ClientGameTestContext c){
        c.runOnClient(client->client.options.guiScale().set(2));
        TestWorldSave save;double[] riceState=new double[3];
        try(var world=c.worldBuilder().create()){
            save=world.getWorldSave();var s=world.getServer();s.runCommand("time set day");s.runCommand("weather clear");s.runCommand("fill -5 98 -5 8 99 6 minecraft:smooth_stone");tp(c,s,"tp @a 1 100 -1 0 45");s.runCommand("gamemode survival @a");c.waitTicks(10);
            for(var e:Map.of(MILL,"hand_mill",PRESS,"oil_press",FAT,"clay_stove",MIX,"mixing_bowl",RICE,"wok").entrySet()){if(e.getKey().getX()>3)tp(c,s,"tp @a 4 100 -1 0 45");else tp(c,s,"tp @a 1 100 -1 0 45");equip(c,s,"smoke_kitchen:"+e.getValue());click(c,e.getKey().below(),Direction.UP);}
            tp(c,s,"tp @a 4 100 -1 0 55");equip(c,s,"smoke_kitchen:clay_pot");click(c,FAT,Direction.UP);
            tp(c,s,"tp @a 0.5 100 -3.5 0 20");for(int i=0;i<3;i++)s.runCommand("summon minecraft:pig 0.5 100 -1.5 {NoAI:1b}");equip(c,s,"minecraft:iron_axe");
            for(int i=0;i<8;i++){c.runOnClient(client->{for(var e:client.level.entitiesForRendering())if(e instanceof net.minecraft.world.entity.animal.pig.Pig&&e.isAlive()){client.gameMode.attack(client.player,e);client.player.swing(InteractionHand.MAIN_HAND);return;}});c.waitTicks(23);}
            tp(c,s,"tp @a 0.5 100 -1.5 0 45");c.waitTicks(30);s.runOnServer(g->check(count(g,"rendered_fat")==3&&g.getPlayerList().getPlayers().getFirst().getInventory().countItem(Items.PORKCHOP)>0,"Three actual vanilla pig deaths must retain ordinary pork and add exactly three fat portions"));
            tp(c,s,"tp @a 4 100 -1 0 55");select(c,"rendered_fat");for(int i=0;i<3;i++)click(c,FAT,Direction.UP);equip(c,s,"minecraft:coal");click(c,FAT,Direction.NORTH);equip(c,s,"minecraft:air");for(int i=0;i<3;i++)click(c,FAT,Direction.NORTH);equip(c,s,"smoke_kitchen:empty_jar 3");click(c,FAT,Direction.UP);s.runOnServer(g->check(pot(g,FAT).heat==1&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().getCount()==3,"Early extraction must preserve all jars and remain on real low heat"));
            s.runCommand("setblock 2 99 5 minecraft:water");s.runCommand("fillbiome 0 96 0 7 104 7 minecraft:ocean");tp(c,s,"tp @a 2.5 100 4 0 55");equip(c,s,"minecraft:water_bucket");c.getInput().holdKey(o->o.keyShift);c.waitTicks(3);useWater(c);c.getInput().releaseKey(o->o.keyShift);c.waitTicks(3);s.runOnServer(g->check(count(g,"saltwater_bucket")==1,"An actual ocean sample must become a saltwater bucket"));
            tp(c,s,"tp @a 5.5 100 1 0 55");s.runCommand("setblock 6 99 0 minecraft:air");equip(c,s,"minecraft:campfire");click(c,new BlockPos(6,98,0),Direction.UP);equip(c,s,"smoke_kitchen:salt_pan");click(c,new BlockPos(6,99,0),Direction.UP);select(c,"saltwater_bucket");click(c,SALT,Direction.UP);s.runOnServer(g->check(pot(g,SALT).saltwater&&pot(g,SALT).batch.water==6&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().is(Items.BUCKET),"Saltwater filling must preserve the original bucket"));
            s.runCommand("setblock 0 100 2 smoke_kitchen:salt_ore");s.runCommand("setblock 1 100 2 smoke_kitchen:salt_ore");tp(c,s,"tp @a 0.5 100 1 0 40");equip(c,s,"minecraft:stone_pickaxe");for(int x=0;x<2;x++){var pos=new BlockPos(x,100,2);c.runOnClient(client->client.gameMode.startDestroyBlock(pos,Direction.NORTH));for(int n=0;n<65;n++){c.runOnClient(client->client.gameMode.continueDestroyBlock(pos,Direction.NORTH));c.waitTicks(1);}c.runOnClient(client->client.gameMode.stopDestroyBlock());}
            tp(c,s,"tp @a 0.5 100 2.5 180 45");c.waitTicks(15);tp(c,s,"tp @a 1.5 100 2.5 180 45");c.waitTicks(15);s.runOnServer(g->check(count(g,"salt_ore_chunk")==4,"Actual survival pickaxe mining must yield four ore chunks from two ores"));tp(c,s,"tp @a 0.5 100 -1 0 55");select(c,"salt_ore_chunk");for(int i=0;i<4;i++)click(c,MILL,Direction.UP);equip(c,s,"minecraft:air");for(int i=0;i<4;i++)click(c,MILL,Direction.UP);take(c,s,MILL,1);s.runOnServer(g->check(count(g,"salt_crystals")==16,"Four actual milling operations must make sixteen salt crystals"));select(c,"salt_crystals");for(int i=0;i<16;i++)click(c,MILL,Direction.UP);select(c,"empty_jar");click(c,MILL,Direction.UP);equip(c,s,"minecraft:air");click(c,MILL,Direction.UP);take(c,s,MILL,1);s.runOnServer(g->check(count(g,"salt")==1&&count(g,"salt_crystals")==0&&count(g,"empty_jar")==2,"Salt packing must consume sixteen crystals and exactly one jar"));
            equip(c,s,"smoke_kitchen:rapeseed 8");for(int i=0;i<8;i++)click(c,PRESS,Direction.UP);equip(c,s,"minecraft:glass_bottle");click(c,PRESS,Direction.UP);equip(c,s,"minecraft:air");click(c,PRESS,Direction.UP);take(c,s,PRESS,2);s.runOnServer(g->check(count(g,"rapeseed_oil")==1&&count(g,"oil_cake")==2&&pot(g,PRESS).items.stream().allMatch(ItemStack::isEmpty),"Actual pressing must consume eight seeds and one bottle, yielding oil and two byproducts"));
            tp(c,s,"tp @a 4.5 100 1 180 55");until(c,s,g->pot(g,FAT).batch.ready(),1000,"Low heat must actually render the fat without adding oil");equip(c,s,"smoke_kitchen:thermometer");click(c,FAT,Direction.UP);lookAt(c,Vec3.atCenterOf(FAT));c.takeScreenshot("acquisition-low-heat-fat-0.1.8");select(c,"empty_jar");click(c,FAT,Direction.UP);click(c,FAT,Direction.UP);equip(c,s,"minecraft:air");for(int i=0;i<3;i++)click(c,FAT,Direction.NORTH);s.runOnServer(g->check(pot(g,FAT).heat==0&&pot(g,FAT).batch.ingredients.isEmpty()&&count(g,"lard")==1&&count(g,"used_lard")==1&&count(g,"fat_cracklings")==3,"Actual jars must collect eight plus four oil uses and exactly three cracklings"));
            var actual=new ArrayList<ItemStack>();s.runOnServer(g->{for(String id:new String[]{"lard","used_lard","fat_cracklings","salt","rapeseed_oil","oil_cake"})actual.add(g.getPlayerList().getPlayers().getFirst().getInventory().getNonEquipmentItems().stream().filter(x->x.is(KitchenContent.item(id))).findFirst().orElseThrow().copy());});c.setScreen(()->new Products(actual));c.waitTicks(5);c.runOnClient(client->client.getToastManager().clear());c.takeScreenshot("acquisition-real-products-0.1.8");c.runOnClient(client->client.setScreen(null));select(c,"lard"); // Prefer the full jar only for the preview; consume the actual partial jar below.
            c.runOnClient(client->{for(int i=0;i<36;i++)if(client.player.getInventory().getItem(i).is(KitchenContent.item("used_lard"))){if(i>8){client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,i,7,net.minecraft.world.inventory.ContainerInput.SWAP,client.player);client.player.getInventory().setSelectedSlot(7);}else client.player.getInventory().setSelectedSlot(i);return;}throw new AssertionError("Actual half jar is missing");});c.waitTicks(5);for(int i=0;i<4;i++)click(c,MIX,Direction.UP);s.runOnServer(g->check(pot(g,MIX).batch.oil==4&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().is(KitchenContent.item("empty_jar")),"The four real remaining oil measures must return the empty jar"));
            tp(c,s,"tp @a 2.5 100 4 0 55");equip(c,s,"smoke_kitchen:empty_water_jug");useWater(c);s.runOnServer(g->check(count(g,"water_jug")==1,"A real water source must refill one jug"));select(c,"water_jug");tp(c,s,"tp @a 4.5 100 1 180 55");for(int i=0;i<6;i++)click(c,MIX,Direction.UP);for(int i=0;i<2;i++)click(c,FAT,Direction.UP);s.runOnServer(g->check(pot(g,MIX).batch.water==6&&pot(g,FAT).batch.water==2&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().is(KitchenContent.item("empty_water_jug")),"Eight exact jug measures must leave one empty jug and eight water measures"));
            tp(c,s,"tp @a 0.5 100 -1 0 55");equip(c,s,"smoke_kitchen:rice_paddy");click(c,MILL,Direction.UP);equip(c,s,"minecraft:air");click(c,MILL,Direction.UP);take(c,s,MILL,2);s.runOnServer(g->check(count(g,"rice")==1&&count(g,"rice_husk")==1,"Actual dehusking must yield one rice and one husk"));select(c,"rice");tp(c,s,"tp @a 4.5 100 1 180 55");click(c,FAT,Direction.UP);equip(c,s,"smoke_kitchen:wooden_lid");click(c,FAT,Direction.UP);equip(c,s,"minecraft:coal");click(c,FAT,Direction.NORTH);equip(c,s,"minecraft:air");for(int i=0;i<3;i++)click(c,FAT,Direction.NORTH);until(c,s,g->pot(g,FAT).batch.ready(),1800,"Raw rice must actually boil, simmer and cook in its two water measures");for(int i=0;i<3;i++)click(c,FAT,Direction.NORTH);take(c,s,FAT,1);s.runOnServer(g->{var rice=g.getPlayerList().getPlayers().getFirst().getInventory().getNonEquipmentItems().stream().filter(x->x.is(KitchenContent.item("cooked_rice"))).findFirst().orElseThrow();check(!rice.has(DataComponents.USE_REMAINDER),"Loose rice must not invent a bowl");var p=new Gson().fromJson(rice.get(DataComponents.CUSTOM_DATA).copyTag().getStringOr("kitchen_portion",""),CookingBatch.Portion.class);riceState[0]=p.cooked;riceState[1]=p.maximumTemperature;riceState[2]=p.lowHeatSeconds;});select(c,"cooked_rice");click(c,RICE,Direction.UP);s.runOnServer(g->{var p=pot(g,RICE).batch.ingredients.getFirst();check(p.id.equals("rice_cooked")&&p.cooked==riceState[0]&&p.maximumTemperature==riceState[1]&&p.lowHeatSeconds==riceState[2]&&!p.needsWater&&p.priorCounts.isEmpty(),"Actual cooked-rice transfer must retain preparation but record a fresh dry pot");});
            until(c,s,g->pot(g,SALT).items.stream().anyMatch(x->x.is(KitchenContent.item("salt_crystals"))),2600,"Real elapsed campfire heat must finish the ocean salt sample");tp(c,s,"tp @a 5 100 1 180 55");take(c,s,SALT,1);s.runOnServer(g->check(count(g,"salt_crystals")==4&&pot(g,SALT).batch.water==0&&!pot(g,SALT).saltwater,"Ocean evaporation must yield exactly four crystals and clear the brine state"));tp(c,s,"tp @a 3.5 100 -4.5 0 15");lookAt(c,new Vec3(3.5,100.5,.5));c.waitTicks(80);c.getInput().holdKey(o->o.keyShift);c.waitTicks(5);c.takeScreenshot("acquisition-finished-stations-0.1.8");c.getInput().releaseKey(o->o.keyShift);c.waitTicks(3);
        }
        try(var world=save.open()){c.waitTicks(10);world.getServer().runOnServer(g->{var p=pot(g,RICE).batch.ingredients.getFirst();check(p.id.equals("rice_cooked")&&p.cooked==riceState[0]&&p.lowHeatSeconds==riceState[2],"Actual world reopening must retain the converted rice history");check(count(g,"lard")==1&&count(g,"used_lard")==0&&count(g,"empty_jar")==1&&count(g,"fat_cracklings")==3&&count(g,"salt")==1&&count(g,"rapeseed_oil")==1&&count(g,"salt_crystals")==4&&count(g,"empty_water_jug")==1,"All actual products and returned containers must survive reopening without duplication");check(pot(g,MIX).batch.oil==4&&pot(g,MIX).batch.water==6&&pot(g,FAT).heat==0,"Measured liquids and the shut burner must survive saving");});c.takeScreenshot("acquisition-after-reload-0.1.8");}
    }
    private static final class Products extends Screen{
        private final List<ItemStack> stacks;Products(List<ItemStack> stacks){super(Component.literal("Actual kitchen products"));this.stacks=stacks;}
        @Override public void extractRenderState(GuiGraphicsExtractor g,int x,int y,float delta){g.fill(0,0,width,height,0xff273038);g.centeredText(font,"SMOKE KITCHEN 0.1.8 | actual produced items",width/2,10,0xffffffff);int pitch=(width-24)/3;for(int i=0;i<stacks.size();i++){int px=12+i%3*pitch,py=32+i/3*105;var stack=stacks.get(i);g.fill(px,py,px+pitch-6,py+96,0xffb9b5a8);g.pose().pushMatrix();g.pose().translate(px+(pitch-56)/2f,py+4).scale(3);g.item(stack,0,0);g.itemDecorations(font,stack,0,0);g.pose().popMatrix();int lineY=py+58;for(var line:font.split(stack.getHoverName(),pitch-12)){g.text(font,line,px+5,lineY,0xff17232b,false);lineY+=10;}if(stack.isDamageableItem())g.text(font,(stack.getMaxDamage()-stack.getDamageValue())+" / "+stack.getMaxDamage(),px+5,py+82,0xff17232b,false);}}
    }
}
